            let str2_ptr = emu.maps.read_dword(emu.regs().get_esp() + 8).unwrap_or(0) as u64;
            let _len2 = emu.maps.read_dword(emu.regs().get_esp() + 12).unwrap_or(0) as i32;
            let ignore_case = emu.maps.read_dword(emu.regs().get_esp() + 16).unwrap_or(0);
