            let vol_name_ptr = emu.maps.read_dword(emu.regs().get_esp() + 4).unwrap_or(0) as u64;
            let vol_name_size = emu.maps.read_dword(emu.regs().get_esp() + 8).unwrap_or(0) as u64;
            let serial_ptr = emu.maps.read_dword(emu.regs().get_esp() + 12).unwrap_or(0) as u64;
            let max_comp_ptr = emu.maps.read_dword(emu.regs().get_esp() + 16).unwrap_or(0) as u64;
            let flags_ptr = emu.maps.read_dword(emu.regs().get_esp() + 20).unwrap_or(0) as u64;
            let fs_name_ptr = emu.maps.read_dword(emu.regs().get_esp() + 24).unwrap_or(0) as u64;
            let fs_name_size = emu.maps.read_dword(emu.regs().get_esp() + 28).unwrap_or(0) as u64;
            let root = if root_ptr != 0 {
                emu.maps.read_string(root_ptr)
            } else {
                String::from("C:\\")
            };
            if vol_name_ptr != 0 && vol_name_size > 0 {
                emu.maps.write_string(vol_name_ptr, "MWEMU");
            }
            if serial_ptr != 0 {
                emu.maps.write_dword(serial_ptr, 0x12345678);
            }
            if max_comp_ptr != 0 {
                emu.maps.write_dword(max_comp_ptr, 255);
            }
            if flags_ptr != 0 {
                emu.maps.write_dword(flags_ptr, 0x700ff);
            }
            if fs_name_ptr != 0 && fs_name_size > 0 {
                emu.maps.write_string(fs_name_ptr, "NTFS");
            }
            log_red!(emu, "kernelbase!GetVolumeInformationA '{}'", root);
            emu.regs_mut().rax = 1;
            for _ in 0..8 {
                emu.stack_pop32(false);
            }
